contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We supply arrays describing modelURIs, modelTypes, customAttributes and expect that
    // for the currently unclaimed rounds the contract will mint one fighter per win for msg.sender
    // and emit Claimed when at least one is minted. We cannot read events here, so we assert
    // that getUnclaimedRewards before equals the number of mints (claimIndex) and after claim it becomes zero.

    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // precondition: arrays lengths match (claimRewards will index them); otherwise call would revert
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input length mismatch");

        // Observe unclaimed rewards before calling
        uint256 before = c.getUnclaimedRewards(address(this));

        // Perform the state-changing call: this may mint up to `before` fighters (one per win)
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe unclaimed rewards after calling
        uint256 after = c.getUnclaimedRewards(address(this));

        // General property:
        // If the call did not revert then the number of unclaimed rewards for this address must be non-increasing,
        // and after the call it must be strictly less than or equal to before, and the difference cannot exceed the
        // provided number of reward descriptions (modelURIs.length). Also, if before==0 then claimRewards should not mint anything
        // so after==0. We assert a single combined predicate.
        assert(
            // if reverted, we cannot reason about state-change so require that it reverted only when inputs insufficient
            (
                reverted
            ) || (
                // not reverted: after <= before
                after <= before
                // and number of consumed claims <= provided descriptions
                && (before - after) <= modelURIs.length
                // and if nothing was claimable before, nothing becomes claimable after
                && ( (before == 0) ? (after == 0) : true )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call claimRewards and assert that if it does not revert then
    // getUnclaimedRewards(address(this)) does not increase and the number of
    // consumed rewards is at most the number of provided descriptions.
    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // inputs must be aligned or claimRewards will revert immediately
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length, "input length mismatch");

        // Observe unclaimed rewards before calling
        uint256 before = c.getUnclaimedRewards(address(this));

        // perform the call, catch revert
        bool reverted = false;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe unclaimed rewards after calling
        uint256 afterCall = c.getUnclaimedRewards(address(this));

        // Single assert: if the call did not revert then afterCall <= before and
        // the number of consumed rewards (before - afterCall) cannot exceed modelURIs.length.
        // If it reverted we do not assume anything about state change.
        assert(
            reverted || (
                afterCall <= before && (before - afterCall) <= modelURIs.length
            )
        );
    }

    receive() external payable {}
}

