contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call claimRewards and assert that when it succeeds, getUnclaimedRewards(addr)
    // decreases by at least the number of rewards minted (the Claimed event amount).
    // We cannot read events here, so instead we observe getUnclaimedRewards before/after
    // and assert that if claimRewards did not revert then after <= before and (before - after) >= 0
    // and also that if the function emitted Claimed then the decrease is >=1. Since we can't read events,
    // we instead require that when claimRewards succeeds it must decrease getUnclaimedRewards by at least 0
    // (i.e. be non-increasing) and that if it consumed any rounds (numRoundsClaimed advanced)
    // then getUnclaimedRewards strictly decreases. We observe numRoundsClaimed via public getter.

    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // lengths must match else claimRewards will revert immediately; ensure both success and revert paths are reachable by caller choices
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length);

        // observe before values
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 beforeRoundsClaimed = c.numRoundsClaimed(address(this));

        bool reverted = false;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 afterRoundsClaimed = c.numRoundsClaimed(address(this));

        // If the call reverted we assert nothing about state-change; if it succeeded we assert:
        // 1) unclaimed rewards did not increase (afterUnclaimed <= beforeUnclaimed)
        // 2) if numRoundsClaimed increased then unclaimed rewards strictly decreased (afterUnclaimed < beforeUnclaimed)
        assert(reverted || (afterUnclaimed <= beforeUnclaimed && (afterRoundsClaimed > beforeRoundsClaimed ? afterUnclaimed < beforeUnclaimed : true)));
    }

    receive() external payable {}
}

contract InvMutTest {
