    constructor(C _c) { c = _c; }

    // Single public entry performing the property check described above.
    // We call claimRewards and then assert that if it succeeded then
    // getUnclaimedRewards(address(this)) <= before and
    // numRoundsClaimed(address(this)) >= before.
    function run(string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        // ensure lengths match to allow success path when appropriate
        require(modelURIs.length == modelTypes.length && modelURIs.length == customAttributes.length);

        // observe before-values
        uint256 beforeUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 beforeRounds = c.numRoundsClaimed(address(this));

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.getUnclaimedRewards(address(this));
        uint32 afterRounds = c.numRoundsClaimed(address(this));

        // If the call succeeded (not reverted) then unclaimed did not increase and rounds did not decrease.
        assert(reverted || (afterUnclaimed <= beforeUnclaimed && afterRounds >= beforeRounds));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry exercising pickWinner and checking the global invariants described
    function run(uint256[] calldata winners, uint256 preRoundId) public payable {
        require(winners.length > 0);
        // preRoundId must be the current roundId of c to make the property meaningful
        // read the before-values
        uint256 beforeRoundId = c.roundId();
        // constrain input so we operate on the current round
        require(preRoundId == beforeRoundId);

        // record fighter points and totalPoints before calling pickWinner
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersLength = winners.length;
        uint256[] memory beforePoints = new uint256[](winnersLength);
        for (uint256 i = 0; i < winnersLength; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
        }

        // must set winnersPerPeriod to winners.length first (only an admin can; test contract is owner since fresh deploy)
        // adjust admin assumed true for deployer; call updateWinnersPerPeriod
        c.updateWinnersPerPeriod(winnersLength);

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observations after call
        uint256 afterRoundId = c.roundId();

        // build condition: if pickWinner did not revert then
        // 1) afterRoundId == beforeRoundId + 1
        // 2) isSelectionComplete[beforeRoundId] == true
        // 3) for each winner, fighterPoints[winner] == 0
        // 4) totalPoints decreased by sum of beforePoints
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winnersLength; i++) {
            sumBefore += beforePoints[i];
        }

        if (!reverted) {
            // check conditions via single assert combining them
            bool condRound = (afterRoundId == beforeRoundId + 1);
            bool condComplete = c.isSelectionComplete(beforeRoundId);
            bool condPointsZero = true;
            for (uint256 i = 0; i < winnersLength; i++) {
                if (c.fighterPoints(winners[i]) != 0) {
                    condPointsZero = false;
                    break;
                }
            }
            bool condTotal = (c.totalPoints() + sumBefore == beforeTotalPoints);
            assert(condRound && condComplete && condPointsZero && condTotal == true);
        } else {
            // If it reverted, then we assert that at least one of the external preconditions failed:
            // either winners.length must equal winnersPerPeriod (we set it), or selection already complete for that round,
            // or caller wasn't admin (but deployer should be admin). To keep a general property, require that if it reverted
            // then isSelectionComplete[beforeRoundId] is true or winners length doesn't match current winnersPerPeriod.
            bool mismatch = (winnersLength != c.winnersPerPeriod());
            bool already = c.isSelectionComplete(beforeRoundId);
            assert(mismatch || already);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the property test
    function run(uint256[] calldata winners) public payable {
        // require at least one winner input
        require(winners.length > 0);

        // read before-values
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersPer = c.winnersPerPeriod();

        // we will set winnersPerPeriod to winners.length so pickWinner can succeed
        c.updateWinnersPerPeriod(winners.length);

        // record fighter points before call
        uint256 winnersLength = winners.length;
        uint256[] memory beforePoints = new uint256[](winnersLength);
        for (uint256 i = 0; i < winnersLength; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
        }

        // call pickWinner (must be a top-level state-changing call)
        bool didRevert;
        try c.pickWinner(winners) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observations after call
        uint256 afterRoundId = c.roundId();
        bool becameComplete = c.isSelectionComplete(beforeRoundId);
        uint256 afterTotalPoints = c.totalPoints();

        // compute sum of beforePoints
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < winnersLength; i++) {
            sumBefore += beforePoints[i];
        }

        // build condition: if call did not revert then all invariants must hold; if it reverted then at least one external precondition must have failed
        // Note: all must be combined into a single assert
        bool successCase = (!didRevert) &&
            (afterRoundId == beforeRoundId + 1) &&
            becameComplete &&
            (afterTotalPoints + sumBefore == beforeTotalPoints);

        // verify each winner's points are zero in success case
        for (uint256 i = 0; i < winnersLength; i++) {
            successCase = successCase && (!didRevert ? (c.fighterPoints(winners[i]) == 0) : true);
        }

        // If reverted, then either winners length did not match winnersPerPeriod at time of pick (we set it, but pickWinner might require admin role),
        // or selection was already complete for the round, or caller wasn't admin. We observe that if reverted then either isSelectionComplete(beforeRoundId) is true
        // or winners.length != c.winnersPerPeriod() (current), or msg sender lacked admin (we can't observe directly), so we allow the observable failures.
        bool revertCase = didRevert && (c.isSelectionComplete(beforeRoundId) || (winners.length != c.winnersPerPeriod()));

        assert(successCase || revertCase);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the property test
    function run(uint256[] calldata winners) public payable {
        // need at least one winner input
        require(winners.length > 0);

        // record observable state before
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersPer = c.winnersPerPeriod();

        // Adjust winnersPerPeriod so pickWinner can accept this winners length
        // This call may revert if msg.sender is not admin; that's fine — we treat subsequent pickWinner outcome accordingly.
        bool setSucceeded;
        try c.updateWinnersPerPeriod(winners.length) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        // capture fighter points for the provided winner ids before calling pickWinner
        uint256 n = winners.length;
        uint256[] memory beforePoints = new uint256[](n);
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < n; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
            sumBefore += beforePoints[i];
        }

        // attempt pickWinner; record whether it reverted
        bool pickReverted;
        try c.pickWinner(winners) {
            pickReverted = false;
        } catch {
            pickReverted = true;
        }

        // read observable state after
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();
        bool becameComplete = c.isSelectionComplete(beforeRoundId);

        // check winners' points after
        bool winnersZero = true;
        for (uint256 i = 0; i < n; i++) {
            if (c.fighterPoints(winners[i]) != 0) {
                winnersZero = false;
                break;
            }
        }

        // Build the general rule as a single assert:
        // If pickWinner succeeded (did not revert) then:
        //   - afterRoundId == beforeRoundId + 1
        //   - isSelectionComplete(beforeRoundId) == true
        //   - each selected winner's fighterPoints == 0
        //   - afterTotalPoints + sumBefore == beforeTotalPoints
        // Otherwise (if pickWinner reverted) then none of those success conditions should hold simultaneously.
        bool successConditions = (
            !pickReverted &&
            afterRoundId == beforeRoundId + 1 &&
            becameComplete &&
            winnersZero &&
            afterTotalPoints + sumBefore == beforeTotalPoints
        );

        // If pickWinner reverted, ensure that the success conditions are NOT all true.
        // This avoids the trivial case where both sides are true.
        bool revertSafe = pickReverted ? !(
            afterRoundId == beforeRoundId + 1 &&
            becameComplete &&
            winnersZero &&
            afterTotalPoints + sumBefore == beforeTotalPoints
        ) : true;

        assert(successConditions || revertSafe);
    }

    receive() external payable {}
}

