    // one public function performing the property test
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        // observe before-state
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersPer = c.winnersPerPeriod();

        // capture fighter points for the provided winner ids before calling pickWinner
        uint256 n = winners.length;
        uint256[] memory beforePoints = new uint256[](n);
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < n; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
            sumBefore += beforePoints[i];
        }

        // try to set winnersPerPeriod to match input length so pickWinner can accept it
        bool setSucceeded;
        try c.updateWinnersPerPeriod(winners.length) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        // attempt pickWinner; record whether it reverted
        bool pickReverted;
        try c.pickWinner(winners) {
            pickReverted = false;
        } catch {
            pickReverted = true;
        }

        // observe after-state
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // check that for the prior round (beforeRoundId) selection-complete is true after success
        bool becameComplete = c.isSelectionComplete(beforeRoundId);

        // check winners' points after
        bool winnersZero = true;
        for (uint256 i = 0; i < n; i++) {
            if (c.fighterPoints(winners[i]) != 0) {
                winnersZero = false;
                break;
            }
        }

        // successConditions should hold exactly when pickWinner did not revert
        bool successConditions = (
            !pickReverted &&
            afterRoundId == beforeRoundId + 1 &&
            becameComplete &&
            winnersZero &&
            // afterTotalPoints + sumBefore == beforeTotalPoints  (rewritten to avoid subtraction in assert)
            beforeTotalPoints == afterTotalPoints + sumBefore
        );

        // If pickWinner reverted then it must NOT be that all successConditions hold.
        // The final assert enforces that either successConditions holds, or (pickReverted and NOT successConditions).
        assert(successConditions || (pickReverted && !successConditions));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry that performs the property-based check
    function run(uint256[] calldata winners) public payable {
        // need at least 1 winner id
        require(winners.length > 0);

        // read observable pre-state
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();

        uint256 n = winners.length;
        uint256[] memory beforePoints = new uint256[](n);
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < n; i++) {
            beforePoints[i] = c.fighterPoints(winners[i]);
            sumBefore += beforePoints[i];
        }

        // try to set winnersPerPeriod so pickWinner will accept this length
        bool setOk;
        try c.updateWinnersPerPeriod(n) {
            setOk = true;
        } catch {
            setOk = false;
        }

        // attempt pickWinner and capture whether it reverted
        bool pickReverted;
        try c.pickWinner(winners) {
            pickReverted = false;
        } catch {
            pickReverted = true;
        }

        // read observable post-state
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // check whether prior round became selection-complete
        bool becameComplete = c.isSelectionComplete(beforeRoundId);

        // check winners' points became zero
        bool winnersZero = true;
        for (uint256 i = 0; i < n; i++) {
            if (c.fighterPoints(winners[i]) != 0) {
                winnersZero = false;
                break;
            }
        }

        // successConditions expected when pickWinner did not revert and update succeeded
        bool successConditions = (
            setOk &&
            !pickReverted &&
            afterRoundId == beforeRoundId + 1 &&
            becameComplete &&
            winnersZero &&
            // totalPoints decreased exactly by sumBefore
            beforeTotalPoints == afterTotalPoints + sumBefore
        );

        // The property: either the successful effects hold, or pickWinner reverted (in which case not all success effects hold)
        assert(successConditions || pickReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for property-based testing
    // params: callers must be this contract (it is), pass an array of token ids to pick as winners
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        // ensure this contract is admin so pickWinner can be called
        // adjustAdminAccess is callable by owner only; the checker deploys C with owner = address(this) (InvMutTest deployed C)
        // But we can't assume that; instead we attempt to make this contract an admin by calling transferOwnership to set owner to this contract if possible.
        // However we are only allowed to call c through its public surface. transferOwnership requires msg.sender == _ownerAddress, which during fresh deploy will be this contract (deployer of C), so this call will revert if not owner. To be safe, we don't rely on change of ownership.
        // The test will try to call pickWinner; if it reverts due to not admin, we capture that and assert consequences.

        // Read pre-state
        uint256 preRoundId = c.roundId();
        uint256 preTotalPoints = c.totalPoints();
        uint256 winnersPer = c.winnersPerPeriod();
        bool reverted;

        // capture fighterPoints for provided winners up to their ids
        uint256 len = winners.length;
        uint256[] memory prePoints = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            // fighterPoints is public mapping(uint256 => uint256)
            prePoints[i] = c.fighterPoints(winners[i]);
        }

        // attempt the state-changing call
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 postRoundId = c.roundId();
        uint256 postTotalPoints = c.totalPoints();

        // If call reverted then nothing should have changed: roundId and totalPoints remain equal
        if (reverted) {
            assert(postRoundId == preRoundId && postTotalPoints == preTotalPoints);
            return;
        }

        // If call succeeded then winners.length must equal winnersPerPeriod and pre-selection must not have been already complete for that round
        // Check that winners.length equals winnersPer
        // Also rule: for each winner id passed, fighterPoints[id] should be zero and totalPoints decreased by sum(prePoints)
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < len; i++) {
            sumPoints += prePoints[i];
        }

        // build condition: winners length equals winnersPer and postRoundId == preRoundId + 1 and postTotalPoints == preTotalPoints - sumPoints
        // and every passed winner now has fighterPoints == 0
        bool allZero = true;
        for (uint256 i = 0; i < len; i++) {
            if (c.fighterPoints(winners[i]) != 0) { allZero = false; break; }
        }

        assert(len == winnersPer && postRoundId == preRoundId + 1 && postTotalPoints + sumPoints == preTotalPoints && allZero);
    }

    // allow receiving ether if needed
    receive() external payable {}
}

