contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will attempt to call pickWinner to create winners for multiple rounds
    // then call claimRewards from this contract and assert that number of minted tokens
    // (observable via FighterFarm.doesTokenExist on minted ids is not available here) is
    // reflected by the Claimed event emission behavior — since we cannot inspect events,
    // instead we assert that the returned getUnclaimedRewards before claiming is >= the
    // Claimed count emitted by claimRewards (we capture claimed count via the function's
    // logic because claimRewards emits Claimed only when claimIndex>0). To observe effect,
    // we rely on getUnclaimedRewards view and that after claimRewards, getUnclaimedRewards is zero
    // for rounds already processed: thus claimIndex equals prior getUnclaimedRewards.

    // We take arrays to create two rounds worth of winners via pickWinner, then the test
    // calls claimRewards and verifies getUnclaimedRewards reduces accordingly.

    function run(uint256[] calldata winnersRound0, uint256[] calldata winnersRound1,
                 string[] calldata modelURIs, string[] calldata modelTypes,
                 uint256[2][] calldata customAttributes) public payable {
        require(winnersRound0.length == winnersRound1.length); // keep winnersPerPeriod consistent
        // Ensure this contract is admin: caller of pickWinner must be admin; c was deployed with owner as deployer,
        // but our test contract is not that owner. Therefore instead of calling pickWinner, we only observe getUnclaimedRewards
        // and claimRewards behavior: we require there is at least one prior round (roundId > 0) by reading getUnclaimedRewards and
        // proceed only if there are unclaimed rewards. However we cannot require on c state. So we will call claimRewards and then
        // assert that after claiming, getUnclaimedRewards returns 0 for this claimer (no dangling unclaimed for processed rounds).

        // Read unclaimed before
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // Try to claim; claimRewards may revert if model arrays sizes mismatch with needed amount. To avoid revert we craft constraints:
        // If unclaimedBefore is 0 then call with empty arrays; otherwise require provided arrays length >= unclaimedBefore.
        if (unclaimedBefore == 0) {
            // call with empty arrays; should be a no-op and not revert
            c.claimRewards(new string[](0), new string[](0), new uint256[2][](0));
            uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));
            // general rule: if nothing unclaimed before, still nothing unclaimed after
            assert(unclaimedAfter == 0);
        } else {
            require(modelURIs.length >= unclaimedBefore && modelTypes.length >= unclaimedBefore && customAttributes.length >= unclaimedBefore);
            // perform claim
            c.claimRewards(modelURIs, modelTypes, customAttributes);
            uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));
            // General rule: after claiming, unclaimed rewards for this claimer must be 0 (they claimed all rounds up to current round)
            assert(unclaimedAfter == 0);
        }
    }

    receive() external payable {}
}

