        uint32 afterRoundsClaimed = c.numRoundsClaimed(address(this));

        // General invariant rule:
        // - If the call reverted, then state must be unchanged for observable parts (rounds claimed and unclaimed rewards)
        // - If it did not revert, then the number of rounds claimed increased by at most beforeUnclaimed,
        //   and afterUnclaimed + (afterRoundsClaimed - beforeRoundsClaimed) == beforeUnclaimed
        if (reverted) {
            assert(afterUnclaimed == beforeUnclaimed && afterRoundsClaimed == beforeRoundsClaimed);
        } else {
            uint32 roundsDelta = afterRoundsClaimed - beforeRoundsClaimed;
            // roundsDelta must be <= beforeUnclaimed and >= 0 (uint32 ensures >=0)
            // and total effective claimed rewards equals decrease in unclaimed rewards
            // avoid underflow: compute in uint256
            uint256 claimedEffective = uint256(beforeUnclaimed) - afterUnclaimed;
            assert(uint256(roundsDelta) <= uint256(beforeUnclaimed) && claimedEffective == uint256(roundsDelta));
        }
    }
