        uint256 afterRound = c.roundId();

        // If call succeeded and advanced round by exactly 1, then the previous round index is beforeRound
        if (!reverted) {
            // Must have advanced exactly one round
            // We assert properties in a single assert below, but do some view-only reads to prepare
            // Read fighterPoints for each winner after the call
            uint256[] memory afterPoints = new uint256[](winnersLen);
            address[] memory recordedOwners = c.winnerAddresses(beforeRound);
            for (uint256 i = 0; i < winnersLen; i++) {
