            bool allZero = true;
            for (uint256 i = 0; i < winnersLen; i++) {
                if (afterPoints[i] != 0) { allZero = false; break; }
            }

            bool recordedLenOk = (recordedOwners.length == winnersLen);

            // single assert expressing the general rule
            assert(
                afterRound == beforeRound + 1 &&
                allZero &&
                recordedLenOk || reverted
            );
        } else {
