contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a dynamic array of winners and an admin flag controlling caller identity.
    // The test will assume msg.sender of this contract is already admin in freshly deployed C
    // (constructor of C sets deployer as admin), and this InvMutTest contract deployed C.
    // So calls from this contract satisfy isAdmin checks.
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0 && winners.length <= 5); // keep bounded for gas

        // read initial round and isSelectionComplete for it
        uint256 beforeRound = c.roundId();
        bool beforeComplete = c.isSelectionComplete(beforeRound);

        // compute sum of fighterPoints for the supplied winners and read each fighter's owner to ensure ownerOf is callable
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            // reading fighterPoints via public getter
            sumPoints += c.fighterPoints(winners[i]);
            // also read owner to ensure ownerOf is valid for token id
            address owner = c._fighterFarmInstance().ownerOf(winners[i]);
            // owner is only observed; no use beyond ensuring view is callable
            if (owner == address(0)) {
                // if owner is zero, then pickWinner would revert when trying to access ownerOf in implementation,
                // so skip asserting on that particular input by forcing a revert here
                revert("invalid owner for provided winner id");
            }
        }

        // Call pickWinner; must supply exact winnersPerPeriod length or pickWinner will revert.
        // So we require the provided winners length equals winnersPerPeriod read from contract.
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp, "must provide exact winnersPerPeriod entries");

        // perform the state-changing call and capture whether it reverts
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: read post values
        uint256 afterRound = c.roundId();
        bool afterComplete = c.isSelectionComplete(beforeRound);

        // compute sum of fighterPoints after
        uint256 sumPointsAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumPointsAfter += c.fighterPoints(winners[i]);
        }

        // GENERAL RULE asserted:
        // If pickWinner did not revert then:
        // - isSelectionComplete for the previous round (beforeRound) must be true
        // - roundId must have incremented by 1
        // - the sum of fighterPoints for the chosen winners must have decreased by exactly the amount they contributed before (i.e., their points were zeroed)
        // Note: we avoid underflow by expressing decrease as sumPointsAfter == 0 and sumPoints >= sumPointsAfter
        assert(
            reverted || (
                afterComplete == true
                && afterRound == beforeRound + 1
                && sumPointsAfter == 0
                && sumPoints >= sumPointsAfter
            )
        );
    }

    // helper to allow views that return contracts: read fighterFarm instance address via storage accessor
    receive() external payable {}
}

