        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            // read public fighterPoints mapping
            uint256 pts = c.fighterPoints(winners[i]);
            sumPoints += pts;
            // ensure ownerOf is callable through FighterFarm external view by trying a view: ownerOf is on FighterFarm, but C exposes no direct getter for that contract.
            // We only use public surface of C, so we avoid calling ownerOf; instead we rely on pickWinner's behavior when called by admin (this contract is deployer of C and thus admin).
        }

        // perform the state-changing call and catch revert
        bool reverted;
        try c.pickWinner(winners) {
