        //  - each chosen winner's fighterPoints were reset to zero, so their sum after is zero
        //  - totalPoints decreased by exactly the sum of those fighterPoints
        assert(
            reverted || (
                afterRound == beforeRound + 1
                && c.isSelectionComplete(beforeRound) == true
                && sumPointsAfter == 0
                && beforeTotalPoints == afterTotalPoints + sumPoints
            )
        );
    }

