contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Provide winners array; function will attempt pickWinner and assert the general invariant
    function run(uint256[] calldata winners) public {
        // Match current winnersPerPeriod
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp, "input length must match winnersPerPeriod");

        // read current round
        uint256 rid = c.roundId();
        // require selection not yet complete for this round so call can succeed
        require(!c.isSelectionComplete(rid), "selection already complete");

        // record owners and points before
        uint256 len = winners.length;
        address[] memory ownersBefore = new address[](len);
        uint256[] memory pointsBefore = new uint256[](len);
        uint256 sumBefore = 0;
        for (uint256 i = 0; i < len; i++) {
            ownersBefore[i] = address(c._fighterFarmInstance()); // cannot access internal, will fail if used; instead read ownerOf
        }

        // Actually read owners and points via public interface
        for (uint256 i = 0; i < len; i++) {
            ownersBefore[i] = c.ownerOf(winners[i]);
            pointsBefore[i] = c.fighterPoints(winners[i]);
            sumBefore += pointsBefore[i];
        }
        uint256 totalBefore = c.totalPoints();

        // attempt call and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // If it reverted then nothing observable guaranteed except that revert happened
            assert(reverted);
            return;
        }

        // After successful call, check properties for that round (rid)
        bool afterComplete = c.isSelectionComplete(rid);
        uint256 totalAfter = c.totalPoints();

        // winners recorded by contract for that round
        uint256 winnersLength = c.winnerAddresses(rid).length;
        // Collect owners stored in winnerAddresses and compare they match ownersBefore
        bool ownersMatch = true;
        if (winnersLength != len) ownersMatch = false;
        for (uint256 i = 0; i < len && ownersMatch; i++) {
            address wa = c.winnerAddresses(rid)[i];
            // each winner address must equal the ownerOf provided in ownersBefore
            if (wa != ownersBefore[i]) ownersMatch = false;
        }

        // Check fighterPoints for selected ids are zero
        bool pointsZero = true;
        for (uint256 i = 0; i < len; i++) {
            if (c.fighterPoints(winners[i]) != 0) pointsZero = false;
        }

        // totalPoints must decrease by exactly sumBefore
        bool totalDecreasedCorrect = (totalBefore == totalAfter + sumBefore);

        // Final general assertion: either call reverted (handled above) or all these hold
        assert(afterComplete && ownersMatch && pointsZero && totalDecreasedCorrect);
    }

    // receive to accept ETH if ever needed
    receive() external payable {}
}
